<section id="play" class="screen play-screen" hidden>
  <style>
    #play.play-screen {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 16px;
      box-sizing: border-box;
      width: 100%;
      max-width: 100%;
      padding: 16px;
      color: var(--j2-text, #f5f7ff);
    }
    #play.play-screen[hidden] { display: none; }
    #play #hud {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      box-sizing: border-box;
      width: 100%;
      max-width: 720px;
      font-family: var(--j2-font-heading);
      font-size: clamp(1.5rem, 7vw, 2.25rem);
      font-weight: 800;
      line-height: 1.2;
    }
    #play .hud-item { white-space: nowrap; }
    #play #score { color: var(--j2-primary, #ffd23f); }
    #play #timer { color: var(--j2-secondary, #3ddcff); }
    #play .play-hint {
      margin: 0;
      font-size: 1.125rem;
      color: var(--j2-muted, #b4bedc);
      text-align: center;
    }
    #play .play-area {
      position: relative;
      box-sizing: border-box;
      width: 100%;
      max-width: 720px;
      height: 60vh;
      height: min(60dvh, 480px);
      overflow: hidden;
      background: var(--j2-surface, #151b2e);
      border: 1px solid #26304f;
      border-radius: var(--j2-radius, 12px);
      touch-action: manipulation;
      -webkit-user-select: none;
      user-select: none;
    }
    #play .circle {
      position: absolute;
      box-sizing: border-box;
      width: 64px;
      height: 64px;
      min-width: 44px;
      min-height: 44px;
      margin: 0;
      padding: 0;
      border: 0;
      border-radius: 50%;
      cursor: pointer;
      touch-action: manipulation;
      -webkit-tap-highlight-color: transparent;
    }
  </style>
  <div id="hud">
    <span id="score" class="hud-item">Score: 0</span>
    <span id="timer" class="hud-item">Time: 30</span>
  </div>
  <p class="play-hint">1 point per circle</p>
  <div id="play-area" class="play-area"></div>
  <script>
    (function () {
      // round 30 seconds; circle lifetime 1 second; 1 point per circle
      var ROUND_MS = 30 * 1000;
      var CIRCLE_LIFE_MS = 1000;
      var POINTS_PER_CIRCLE = 1;
      // Minimal build choices, not Requester decisions: circle size and spawn gap.
      var CIRCLE_SIZE = 64;
      var SPAWN_EVERY_MS = 700;
      var COLOURS = ['var(--j2-primary)', 'var(--j2-secondary)', 'var(--j2-accent)'];

      var startScreen = document.getElementById('start');
      var playScreen = document.getElementById('play');
      var area = document.getElementById('play-area');
      var scoreEl = document.getElementById('score');
      var timerEl = document.getElementById('timer');
      var startBtn = document.getElementById('start-btn');

      var score = 0;
      var running = false;
      var endAt = 0;
      var tickId = null;
      var spawnId = null;
      var lives = [];

      function showScore() { scoreEl.textContent = 'Score: ' + score; }
      function showTime(ms) {
        timerEl.textContent = 'Time: ' + Math.max(0, Math.ceil(ms / 1000));
      }

      function removeCircle(c) {
        var i = lives.indexOf(c);
        if (i !== -1) { clearTimeout(c._life); lives.splice(i, 1); }
        if (c.parentNode) { c.parentNode.removeChild(c); }
      }

      function clearCircles() {
        while (lives.length) { removeCircle(lives[0]); }
        area.innerHTML = '';
      }

      function spawn() {
        if (!running) { return; }
        var w = area.clientWidth;
        var h = area.clientHeight;
        var c = document.createElement('button');
        c.type = 'button';
        c.className = 'circle';
        c.tabIndex = -1;
        c.setAttribute('aria-label', 'Circle');
        c.style.left = Math.floor(Math.random() * Math.max(1, w - CIRCLE_SIZE)) + 'px';
        c.style.top = Math.floor(Math.random() * Math.max(1, h - CIRCLE_SIZE)) + 'px';
        c.style.background = COLOURS[Math.floor(Math.random() * COLOURS.length)];
        c.addEventListener('pointerdown', function (e) {
          e.preventDefault();
          if (!running || lives.indexOf(c) === -1) { return; }
          score += POINTS_PER_CIRCLE;
          showScore();
          removeCircle(c);
        });
        area.appendChild(c);
        lives.push(c);
        c._life = setTimeout(function () { removeCircle(c); }, CIRCLE_LIFE_MS);
      }

      function stopTimers() {
        running = false;
        clearInterval(tickId);
        clearInterval(spawnId);
        tickId = null;
        spawnId = null;
        clearCircles();
      }

      function tick() {
        var left = endAt - performance.now();
        if (left <= 0) { finish(); return; }
        showTime(left);
      }

      function finish() {
        stopTimers();
        showTime(0);
        api.score = score;
        playScreen.hidden = true;
        var endScreen = document.getElementById('end');
        if (endScreen) { endScreen.hidden = false; }
        document.dispatchEvent(new CustomEvent('taprush:end', { detail: { score: score } }));
      }

      function start() {
        stopTimers();
        score = 0;
        showScore();
        showTime(ROUND_MS);
        if (startScreen) { startScreen.hidden = true; }
        var endScreen = document.getElementById('end');
        if (endScreen) { endScreen.hidden = true; }
        playScreen.hidden = false;
        running = true;
        endAt = performance.now() + ROUND_MS;
        tickId = setInterval(tick, 100);
        spawn();
        spawnId = setInterval(spawn, SPAWN_EVERY_MS);
      }

      function stop() { stopTimers(); }

      // Hooks for the end screen (start a new round) and the nav (stop a round).
      var api = window.TapRush = { start: start, stop: stop, score: 0 };

      if (startBtn) { startBtn.addEventListener('click', start); }
    })();
  </script>
</section>
