    }
    .j2-nav .nav-link {
      display: flex;
      align-items: center;
      justify-content: center;
      box-sizing: border-box;
      flex: 1 1 0;
      min-width: 44px;
      max-width: 200px;
      min-height: 48px;
      padding: 0 8px;
      font-family: var(--j2-font-body);
      font-size: 1.125rem;
      font-weight: 700;
      text-decoration: none;
      color: var(--j2-secondary, #3ddcff);
      border-radius: var(--j2-radius, 12px);
    }
    .j2-nav .nav-link[aria-current="true"] {
      color: var(--j2-primary, #ffd23f);
      text-decoration: underline;
      text-underline-offset: 6px;
    }
  </style>
  <a class="nav-link" href="#start" aria-current="true">Start</a>
  <a class="nav-link" href="#play">Play</a>
  <a class="nav-link" href="#end">Results</a>
  <script>
    (function () {
      var ids = ['start', 'play', 'end'];
      var links = document.querySelectorAll('.j2-nav .nav-link');

      function showScreen(target) {
        // Stop any round in progress before switching screens.
        if (window.TapRush && typeof window.TapRush.stop === 'function') {
          window.TapRush.stop();
        }
        for (var i = 0; i < ids.length; i++) {
          var el = document.getElementById(ids[i]);
          if (el) { el.hidden = (ids[i] !== target); }
        }
        if (target === 'end') {
          // Make the end screen usable if no round has finished yet.
          var endEl = document.getElementById('end');
          if (endEl) {
            endEl.classList.remove('end-idle');
            endEl.removeAttribute('inert');
          }
        }
        for (var j = 0; j < links.length; j++) {
          var on = links[j].getAttribute('href') === '#' + target;
          if (on) { links[j].setAttribute('aria-current', 'true'); }
          else { links[j].removeAttribute('aria-current'); }
        }
        window.scrollTo(0, 0);
      }

      for (var k = 0; k < links.length; k++) {
        links[k].addEventListener('click', function (e) {
          var target = this.getAttribute('href').slice(1);
          if (ids.indexOf(target) === -1) { return; }
          e.preventDefault();
          showScreen(target);
        });
      }

      // Keep the highlighted link in step with the game's own screen changes.
      function sync() {
