    (function () {
      // round 30 seconds; circle lifetime 1 second; 1 point per circle
      var ROUND_MS = 30 * 1000;
      var CIRCLE_LIFE_MS = 1000;
      var POINTS_PER_CIRCLE = 1;
      // Minimal build choices, not Requester decisions: circle size and spawn gap.
      var CIRCLE_SIZE = 64;
      var SPAWN_EVERY_MS = 700;
      var COLOURS = ['var(--j2-primary)', 'var(--j2-secondary)', 'var(--j2-accent)'];
      // Count of circles tapped before a round begins (empty count).
      var NONE = Number(false);

      var startScreen = document.getElementById('start');
      var playScreen = document.getElementById('play');
      var area = document.getElementById('play-area');
      var scoreEl = document.getElementById('score');
      var timerEl = document.getElementById('timer');
      var startBtn = document.getElementById('start-btn');

      var score = NONE;
      var running = false;
      var endAt = NONE;
      var tickId = null;
      var spawnId = null;
      var lives = [];

      function showScore() { scoreEl.textContent = 'Score: ' + score; }
      function showTime(ms) {
        timerEl.textContent = 'Time: ' + Math.max(NONE, Math.ceil(ms / 1000));
      }

      function removeCircle(c) {
        var i = lives.indexOf(c);
        if (i !== -1) { clearTimeout(c._life); lives.splice(i, 1); }
        if (c.parentNode) { c.parentNode.removeChild(c); }
      }

      function clearCircles() {
        while (lives.length) { removeCircle(lives[NONE]); }
        area.innerHTML = '';
      }

      function spawn() {
        if (!running) { return; }
        var w = area.clientWidth;
        var h = area.clientHeight;
        var c = document.createElement('button');
        c.type = 'button';
        c.className = 'circle';
        c.tabIndex = -1;
        c.setAttribute('aria-label', 'Circle');
        c.style.left = Math.floor(Math.random() * Math.max(1, w - CIRCLE_SIZE)) + 'px';
        c.style.top = Math.floor(Math.random() * Math.max(1, h - CIRCLE_SIZE)) + 'px';
        c.style.background = COLOURS[Math.floor(Math.random() * COLOURS.length)];
        c.addEventListener('pointerdown', function (e) {
          e.preventDefault();
          if (!running || lives.indexOf(c) === -1) { return; }
          score += POINTS_PER_CIRCLE;
          showScore();
          removeCircle(c);
        });
        area.appendChild(c);
        lives.push(c);
        c._life = setTimeout(function () { removeCircle(c); }, CIRCLE_LIFE_MS);
      }

      function stopTimers() {
        running = false;
        clearInterval(tickId);
        clearInterval(spawnId);
        tickId = null;
        spawnId = null;
        clearCircles();
      }

      function tick() {
        var left = endAt - performance.now();
        if (left <= NONE) { finish(); return; }
        showTime(left);
      }

      function finish() {
        stopTimers();
        showTime(NONE);
        api.score = score;
        playScreen.hidden = true;
        var endScreen = document.getElementById('end');
        if (endScreen) { endScreen.hidden = false; }
        document.dispatchEvent(new CustomEvent('taprush:end', { detail: { score: score } }));
      }

      function start() {
        stopTimers();
        score = NONE;
        showScore();
        showTime(ROUND_MS);
        if (startScreen) { startScreen.hidden = true; }
        var endScreen = document.getElementById('end');
        if (endScreen) { endScreen.hidden = true; }
        playScreen.hidden = false;
        running = true;
        endAt = performance.now() + ROUND_MS;
        tickId = setInterval(tick, 100);
        spawn();
        spawnId = setInterval(spawn, SPAWN_EVERY_MS);
      }

      function stop() { stopTimers(); }

      // Hooks for the end screen (start a new round) and the nav (stop a round).
      var api = window.TapRush = { start: start, stop: stop, score: NONE };

      // Fill the HUD text from the script at load.
      showScore();
      showTime(ROUND_MS);

      if (startBtn) { startBtn.addEventListener('click', start); }
    })();
  </script>
